def merge_k_sorted(lists):
    heap = []
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst[0], i, 0))
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)
        out.append(val)
        j += 1
        if j < len(lists[i]):
            heapq.heappush(heap, (lists[i][j], i, j))
    return out

def toposort(graph):
    perm, temp, out = set(), set(), []

    def visit(v):
        if v in perm:
            return
        if v in temp:
            raise ValueError('cycle')
        temp.add(v)
        for w in graph.get(v, []):
            visit(w)
        temp.remove(v)
        perm.add(v)
        out.append(v)

    for v in graph:
        visit(v)
    out.reverse()
    return out

