def matmul(A, B):
    n, m, p = len(A), len(A[0]), len(B[0])
    out = [[0]*p for _ in range(n)]
    for i in range(n):
        for k in range(m):
            for j in range(p):
                out[i][j] += A[i][k]*B[k][j]
    return out

def levenshtein(a, b):
    dp = [[0]*(len(b)+1) for _ in range(len(a)+1)]
    for i in range(len(a)+1): dp[i][0] = i
    for j in range(len(b)+1): dp[0][j] = j
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            cost = 0 if a[i-1]==b[j-1] else 1
            dp[i][j] = min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[-1][-1]

def pascal(n):
    rows = []
    for i in range(n):
        row = [1]*(i+1)
        for j in range(1, i):
            row[j] = rows[i-1][j-1] + rows[i-1][j]
        rows.append(row)
    return rows

def bucket_sort(a):
    n = len(a)
    buckets = [[] for _ in range(n or 1)]
    for x in a:
        i = min(n-1, int(x*n)) if n else 0
        buckets[i].append(x)
    for b in buckets:
        b.sort()
    out = []
    for b in buckets:
        out.extend(b)
    return out

