def kmp_search(text, pat):
    if not pat:
        return 0
    # build lps
    lps = [0]*len(pat)
    j = 0
    for i in range(1,len(pat)):
        while j>0 and pat[i]!=pat[j]:
            j = lps[j-1]
        if pat[i]==pat[j]:
            j+=1
            lps[i]=j
    # search
    j=0
    for i,ch in enumerate(text):
        while j>0 and ch!=pat[j]:
            j=lps[j-1]
        if ch==pat[j]:
            j+=1
            if j==len(pat):
                return i-j+1
    return -1

