import heapq

def astar(grid, start, goal):
    R, C = len(grid), len(grid[0])
    def h(a,b):
        return abs(a[0]-b[0])+abs(a[1]-b[1])
    g = {start:0}
    came = {}
    pq = [(h(start,goal), 0, start)]
    seen = set()
    while pq:
        _, cost, cur = heapq.heappop(pq)
        if cur in seen: continue
        seen.add(cur)
        if cur == goal:
            path = [cur]
            while cur in came:
                cur = came[cur]
                path.append(cur)
            path.reverse()
            return path
        r,c = cur
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc = r+dr, c+dc
            if 0<=nr<R and 0<=nc<C and not grid[nr][nc]:
                nxt = (nr,nc)
                ncst = cost+1
                if nxt not in g or ncst < g[nxt]:
                    g[nxt] = ncst
                    came[nxt] = cur
                    f = ncst + h(nxt, goal)
                    heapq.heappush(pq, (f, ncst, nxt))
    return []

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0]*n
    def find(self, x):
        if self.p[x] != x:
            self.p[x] = self.find(self.p[x])
        return self.p[x]
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb: return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return True

def min_cut_pal(s):
    n = len(s)
    pal = [[False]*n for _ in range(n)]
    for i in range(n-1,-1,-1):
        for j in range(i,n):
            pal[i][j] = (s[i]==s[j]) and (j-i<2 or pal[i+1][j-1])
    dp = [0]*n
    for i in range(n):
        if pal[0][i]:
            dp[i] = 0
        else:
            dp[i] = min(dp[j]+1 for j in range(i) if pal[j+1][i])
    return dp[-1]

