def scc(graph):
    seen=set(); order=[]
    def dfs(v):
        seen.add(v)
        for w in graph.get(v,[]):
            if w not in seen: dfs(w)
        order.append(v)
    for v in graph: 
        if v not in seen: dfs(v)
    rg={}
    for v,ws in graph.items():
        for w in ws: rg.setdefault(w,[]).append(v)
    seen.clear()
    comps=[]
    def dfs2(v, comp):
        seen.add(v); comp.append(v)
        for w in rg.get(v,[]):
            if w not in seen: dfs2(w, comp)
    for v in reversed(order):
        if v not in seen:
            comp=[]; dfs2(v, comp); comps.append(comp)
    return comps

class AVL:
    class N:
        def __init__(self,k):
            self.k=k; self.l=None; self.r=None; self.h=1
    def __init__(self):
        self.root=None
    def _h(self,x): return x.h if x else 0
    def _upd(self,x): x.h=max(self._h(x.l),self._h(x.r))+1
    def _rotR(self,y):
        x=y.l; T2=x.r
        x.r=y; y.l=T2
        self._upd(y); self._upd(x)
        return x
    def _rotL(self,x):
        y=x.r; T2=y.l
        y.l=x; x.r=T2
        self._upd(x); self._upd(y)
        return y
    def _bal(self,x): return self._h(x.l)-self._h(x.r)
    def _ins(self,node,k):
        if not node: return self.N(k)
        if k<node.k: node.l=self._ins(node.l,k)
        else: node.r=self._ins(node.r,k)
        self._upd(node)
        b=self._bal(node)
        if b>1 and k<node.l.k: return self._rotR(node)
        if b<-1 and k>node.r.k: return self._rotL(node)
        if b>1 and k>node.l.k:
            node.l=self._rotL(node.l); return self._rotR(node)
        if b<-1 and k<node.r.k:
            node.r=self._rotR(node.r); return self._rotL(node)
        return node
    def insert(self,k):
        self.root=self._ins(self.root,k)
    def search(self,k):
        cur=self.root
        while cur and cur.k!=k:
            cur=cur.l if k<cur.k else cur.r
        return cur

import heapq

def astar(grid, start, goal):
    R, C = len(grid), len(grid[0])
    def h(a,b):
        return abs(a[0]-b[0])+abs(a[1]-b[1])
    g = {start:0}
    came = {}
    pq = [(h(start,goal), 0, start)]
    seen = set()
    while pq:
        _, cost, cur = heapq.heappop(pq)
        if cur in seen: continue
        seen.add(cur)
        if cur == goal:
            path = [cur]
            while cur in came:
                cur = came[cur]
                path.append(cur)
            path.reverse()
            return path
        r,c = cur
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc = r+dr, c+dc
            if 0<=nr<R and 0<=nc<C and not grid[nr][nc]:
                nxt = (nr,nc)
                ncst = cost+1
                if nxt not in g or ncst < g[nxt]:
                    g[nxt] = ncst
                    came[nxt] = cur
                    f = ncst + h(nxt, goal)
                    heapq.heappush(pq, (f, ncst, nxt))
    return []

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0]*n
    def find(self, x):
        if self.p[x] != x:
            self.p[x] = self.find(self.p[x])
        return self.p[x]
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb: return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return True

def min_cut_pal(s):
    n = len(s)
    pal = [[False]*n for _ in range(n)]
    for i in range(n-1,-1,-1):
        for j in range(i,n):
            pal[i][j] = (s[i]==s[j]) and (j-i<2 or pal[i+1][j-1])
    dp = [0]*n
    for i in range(n):
        if pal[0][i]:
            dp[i] = 0
        else:
            dp[i] = min(dp[j]+1 for j in range(i) if pal[j+1][i])
    return dp[-1]

class SplayTree:
    class Node:
        def __init__(self, key):
            self.key=key; self.l=None; self.r=None; self.p=None
    def __init__(self):
        self.root=None
    def _rotate(self, x):
        p=x.p; g=p.p
        if x==p.l:
            p.l=x.r;  
            if x.r: x.r.p=p
            x.r=p
        else:
            p.r=x.l
            if x.l: x.l.p=p
            x.l=p
        p.p=x; x.p=g
        if g:
            if g.l==p: g.l=x
            else: g.r=x
        else:
            self.root=x
    def _splay(self, x):
        while x.p:
            p=x.p; g=p.p
            if not g:
                self._rotate(x)
            elif (x==p.l) == (p==g.l):
                self._rotate(p); self._rotate(x)
            else:
                self._rotate(x); self._rotate(x)
    def _find(self, key):
        v=self.root; last=None
        while v:
            last=v
            if key==v.key: break
            v=v.l if key<v.key else v.r
        return v or last
    def search(self, key):
        if not self.root: return None
        x=self._find(key); self._splay(x)
        return x if x.key==key else None
    def insert(self, key):
        if not self.root:
            self.root=self.Node(key); return
        x=self._find(key)
        self._splay(x)
        n=self.Node(key)
        if key<x.key:
            n.l=x.l; n.r=x; x.l=None
        else:
            n.r=x.r; n.l=x; x.r=None
        if n.l: n.l.p=n
        if n.r: n.r.p=n
        n.p=None; self.root=n

